create or replace function public.epic_unified_notes_set_readiness(p_note_id uuid,p_visible boolean) returns setof public.epic_unified_notes language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; return query update public.epic_unified_notes n set visible_in_readiness=coalesce(p_visible,false),updated_at=now() where n.note_id=p_note_id and n.note_scope='reservation' and n.source in ('c360','tripworks') returning n.*; end $$;